import type { Octokit } from 'octokit'

type OctokitInstance = InstanceType<typeof Octokit>
type ReposGetContentResponse = Awaited<
  ReturnType<OctokitInstance['rest']['repos']['getContent']>
>['data']
type ReposListForOrgResponse = Awaited<
  ReturnType<OctokitInstance['rest']['repos']['listForOrg']>
>['data']

export type ContentItem = Extract<ReposGetContentResponse, Array<unknown>>[number] & {
  lastModified?: string
}

export type ContentTreeItem = {
  content: ContentItem
  children?: ContentTreeItem[]
}

export type Repository = ReposListForOrgResponse[number]

export type OwnerIdentifier = {
  owner: string
}

export type RepoIdentifier = OwnerIdentifier & {
  repo: string
}

export type ContentIdentifier = RepoIdentifier & {
  path?: string
}

export type FlashCardItem = {
  lineNo: number
  /** fm.json v2의 안정적 카드 id(UUID). 노트 링크의 anchor. 구버전 카드/탭 포맷엔 없다. */
  itemId?: string
  q: string
  a: string
}

export type FlashCardContent = ContentItem & {
  flashCardItems: FlashCardItem[]
}

export type FlashManJsonItem = {
  /** finalize-v2.mjs가 부여하는 안정적 UUID. 구버전 파일엔 없을 수 있다. */
  id?: string
  question: string
  answer: string
}

export type FlashManJson = {
  version: 1
  items: FlashManJsonItem[]
}

/** 힌트 산출물 종류. 각 카드의 hint dir 안에 종류별 파일이 있다. */
export const HINT_ARTIFACT_KEYS = ['hint', 'hi', 'expy', 'nano'] as const
export type HintArtifactKey = (typeof HINT_ARTIFACT_KEYS)[number]

/**
 * 힌트 문서의 엔트리 (flash-man-plugin `/flash-man:make-hints`가 생성).
 * 문서 위치는 `<flash card dir>/.fm/hints/index.json`(현행, 디렉토리당 1개) 또는
 * 카드 파일 옆 `<name>.fm.hints.json`(레거시). `useFlashCardHints` 참고.
 *
 * 산출물 필드(hint/hi/expy/nano)의 값 의미:
 * - 필드 없음 — 미선택 (해당 산출물 없음)
 * - `null` — 선택됨, 생성 대기 (아직 파일 없음)
 * - 문자열 — 생성 완료. 값은 **산출물 파일의 경로**로, 그 값을 담은 힌트 문서가 있는
 *   디렉토리 기준 상대 경로다(레이아웃에 따라 base가 달라진다). 종류별 대표 파일:
 *   hint→`<dir>/README.md`, hi→`<dir>/hi.md`, expy→`<dir>/expy.py`(+형제 `expy.png`,
 *   그리고 플러그인이 스크립트를 실행해 렌더링한 `expy.ipynb` — 앱은 있으면 이것을 우선 표시),
 *   nano→`<dir>/nano.jpg`|`nano.png`(모델 응답 MIME에 따라 다름; `nano.md` 프롬프트는 형제).
 *
 * 하위호환: 구버전은 이 값이 파일이 아니라 **hint dir**(예: `.fm/hints/<uuid|제목>`)였다.
 *   basename에 `.`이 있으면 파일 경로, 없으면 레거시 dir로 해석한다(제목 규칙상 dir명엔
 *   `.`이 없다). 레거시 dir은 위 규칙으로 파일명을 유추하되, nano는 png/jpg가 모호하므로
 *   조회 시 확장자 후보를 시도한다.
 */
export type FlashManHintJsonItem = {
  id?: string // FlashManJsonItem.id가 있으면 이 값 저장
  question?: string // FlashManJsonItem.id 없으면 question, answer 저장
  answer?: string // FlashManJsonItem.id 없으면 question, answer 저장
  hint?: null | string
  hi?: null | string
  expy?: null | string
  nano?: null | string
}

export type FlashManHintJson = {
  version: 1
  items: FlashManHintJsonItem[]
}

export type FlashCardItemWithSummary = FlashCardItem & {
  passRatio: number
}

export type LearningHistoryItem = {
  owner: string
  repo: string
  path: string
  sha: string
  line_no: number
  type: 'pass' | 'fail' | 'fin'
  duration: number
}

export type FilterType = 'all' | 'not-started' | 'in-progress' | 'completed'

export type ViewType = 'tree' | 'list'
