/**
 * 힌트 문서(`.fm/hints/index.json` 또는 레거시 `*.fm.hints.json`) 해석 로직.
 *
 * 두 레이아웃이 카드 파일 단위로 공존한다 (flash-man-plugin `make-hints.mjs`의
 * `resolveHintsDoc`와 동일한 규칙):
 * 1. `<flash card dir>/.fm/hints/index.json` — 현행. 디렉토리당 1개, 모든 카드 파일이 공유.
 * 2. `<name>.fm.hints.json` — 레거시. 이미 존재하는 카드 파일은 플러그인도 계속 여기에 쓴다.
 *
 * 산출물 필드의 경로 값은 **그 값을 담은 문서가 있는 디렉토리 기준 상대 경로**이므로,
 * 레이아웃에 따라 base가 달라진다. 여기서 repo 루트 기준으로 확정한다.
 */
import {
  HINT_ARTIFACT_KEYS,
  type FlashManHintJson,
  type FlashManHintJsonItem,
  type HintArtifactKey,
} from '../types'

/** 힌트 문서 + 그 문서가 있는 디렉토리(경로 값들의 base, repo 루트 기준). */
export type HintsDoc = {
  doc: FlashManHintJson
  baseDir: string
}

/** 카드 매칭 키. id 우선, 없으면 question+answer (레거시 카드). */
export type HintMatchKey = {
  itemId?: string | null
  q: string
  a: string
}

/**
 * 생성 완료되어 열람 가능한 산출물. 경로는 모두 **repo 루트 기준**이다.
 * - `dir`: 산출물 디렉토리 (형제 파일 fetch의 base).
 * - `file`: 스키마에 명시된 대표 파일 경로. nano면 이미지 경로(png/jpg)라 확장자 모호함이
 *   사라진다. 레거시 dir 형식이라 유추 불가한 경우(주로 nano)엔 undefined.
 */
export type AvailableHintArtifact = {
  key: HintArtifactKey
  dir: string
  file?: string
}

/** 레거시 dir 형식일 때 종류별 대표 파일명. nano는 png/jpg 모호로 제외. */
const LEGACY_ARTIFACT_FILE: Partial<Record<HintArtifactKey, string>> = {
  hint: 'README.md',
  hi: 'hi.md',
  expy: 'expy.py',
}

export function dirnameOf(p: string): string {
  const i = p.lastIndexOf('/')
  return i === -1 ? '' : p.slice(0, i)
}

function basename(p: string): string {
  const i = p.lastIndexOf('/')
  return i === -1 ? p : p.slice(i + 1)
}

export function joinPath(...segments: string[]): string {
  return segments.filter(Boolean).join('/')
}

/** 레거시 레이아웃: 카드 파일 옆의 `*.fm.hints.json` 경로. */
export function legacyHintsPathFor(cardFilePath: string): string {
  return cardFilePath.replace(/\.fm\.(json|md)$/, '.fm.hints.json')
}

/** 현행 레이아웃: flash card dir당 하나인 `.fm/hints/index.json` 경로. */
export function hintsIndexPathFor(cardFilePath: string): string {
  return joinPath(dirnameOf(cardFilePath), '.fm/hints/index.json')
}

/**
 * 저장된 문자열 값을 {dir, file}로 해석. basename에 `.`이 있으면 파일 경로(신 스키마),
 * 없으면 레거시 hint dir(제목 규칙상 dir명엔 `.`이 없다). `baseDir`을 붙여 repo 루트 기준으로.
 */
export function resolveArtifactLocation(
  key: HintArtifactKey,
  value: string,
  baseDir: string
): { dir: string; file?: string } {
  if (basename(value).includes('.')) {
    return { dir: joinPath(baseDir, dirnameOf(value)), file: joinPath(baseDir, value) }
  }
  const conv = LEGACY_ARTIFACT_FILE[key]
  const dir = joinPath(baseDir, value)
  return { dir, file: conv ? `${dir}/${conv}` : undefined }
}

/**
 * 카드 ↔ 힌트 엔트리 매칭. flash-man-plugin의 규칙과 동일:
 * id 우선, 없으면 question+answer 정확 일치 (레거시 카드).
 */
export function matchHintEntry(
  hints: FlashManHintJson | null | undefined,
  key: HintMatchKey
): FlashManHintJsonItem | null {
  if (!hints) {
    return null
  }
  if (key.itemId) {
    const byId = hints.items.find((e) => e.id === key.itemId)
    if (byId) {
      return byId
    }
  }
  return hints.items.find((e) => e.question === key.q && e.answer === key.a) ?? null
}

/**
 * 신규 인덱스 우선, **엔트리가 없으면** 레거시로 fallback.
 *
 * 한 디렉토리에 두 문서가 공존할 수 있으므로(카드 파일별로 갈림) 문서 404가 아니라
 * 엔트리 미스 기준으로 넘어가야 한다 — 인덱스가 존재하더라도 레거시 카드 파일의 엔트리는
 * 거기에 없다.
 */
export function pickHintEntry(
  index: HintsDoc | null | undefined,
  legacy: HintsDoc | null | undefined,
  key: HintMatchKey
): { entry: FlashManHintJsonItem; baseDir: string } | null {
  const fromIndex = index ? matchHintEntry(index.doc, key) : null
  if (fromIndex && index) {
    return { entry: fromIndex, baseDir: index.baseDir }
  }
  const fromLegacy = legacy ? matchHintEntry(legacy.doc, key) : null
  if (fromLegacy && legacy) {
    return { entry: fromLegacy, baseDir: legacy.baseDir }
  }
  return null
}

/** 엔트리에서 열람 가능한(문자열 = 생성 완료) 산출물만 골라 경로를 확정한다. */
export function availableArtifacts(
  matched: { entry: FlashManHintJsonItem; baseDir: string } | null
): AvailableHintArtifact[] {
  if (!matched) {
    return []
  }
  return HINT_ARTIFACT_KEYS.flatMap((key) => {
    const value = matched.entry[key]
    return typeof value === 'string'
      ? [{ key, ...resolveArtifactLocation(key, value, matched.baseDir) }]
      : []
  })
}
