import { Octokit } from 'octokit'

import type {
  ContentItem,
  ContentTreeItem,
  FlashCardContent,
  FlashManHintJson,
  FlashManJson,
  OwnerIdentifier,
  RepoIdentifier,
  Repository,
} from '../types'

import { dirnameOf, type HintsDoc } from './hints'

export function makeOctokit(accessToken?: string): Octokit {
  return new Octokit(accessToken ? { auth: accessToken } : {})
}

export async function getOrgRepositories(
  octokit: Octokit,
  { owner }: OwnerIdentifier
): Promise<Repository[]> {
  const resp = await octokit.rest.repos.listForOrg({
    org: owner,
    type: 'all',
  })
  return resp.data
}

export async function getUserRepositories(
  octokit: Octokit,
  { owner }: OwnerIdentifier
): Promise<Repository[]> {
  const resp = await octokit.rest.repos.listForUser({
    username: owner,
    sort: 'updated',
  })
  return resp.data
}

export async function getAuthenticatedUserRepositories(octokit: Octokit, query?: string) {
  const resp = await octokit.rest.repos.listForAuthenticatedUser({
    sort: 'updated',
    // type: 'all',
    affiliation: 'owner,collaborator,organization_member',
    visibility: 'all',
    per_page: 1000,
    query,
  })
  // console.log('getAuthenticatedUserRepositories', resp)
  return resp.data
}

export async function getContents(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  path: string
): Promise<ContentItem | ContentItem[]> {
  try {
    const resp = await octokit.rest.repos.getContent({
      ...repoIdentifier,
      path,
    })
    return resp.data as ContentItem | ContentItem[]
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error(e)
  }
  return []
}

/** 트리에 노출할 파일인지 판정 (숨김 파일 제외, 지원 확장자만). */
function isVisibleFile(name: string): boolean {
  return name.endsWith('.md') || name.endsWith('.txt') || name.endsWith('.fm.json')
}

/**
 * 저장소의 콘텐츠 트리를 조회한다.
 *
 * 기존에는 디렉토리마다 Contents API를 재귀 호출해 N+1 요청이 발생했다.
 * 대신 Git Trees API(`recursive=1`)로 전체 트리를 한 번에 받아, 평면 목록을
 * 클라이언트에서 중첩 구조로 재구성한다 (왕복 1회).
 *
 * Git Trees 응답의 blob `sha`는 Contents API의 blob sha와 동일하므로,
 * 학습 이력 키(sha) 호환성이 유지된다. 트리 소비부는 sha/name/type/path/size
 * 필드만 사용하므로 나머지 Contents 전용 필드는 채우지 않는다.
 *
 * @param path 하위 트리 시작 경로 (''이면 저장소 루트)
 * @param ref  대상 ref (기본 'HEAD')
 */
export async function getContentTree(
  octokit: Octokit,
  { owner, repo }: RepoIdentifier,
  path: string,
  ref = 'HEAD'
): Promise<ContentTreeItem[]> {
  try {
    const resp = await octokit.rest.git.getTree({
      owner,
      repo,
      tree_sha: ref,
      recursive: 'true',
    })

    if (resp.data.truncated) {
      // eslint-disable-next-line no-console
      console.warn(
        `getContentTree: tree for ${owner}/${repo} is truncated; some entries are omitted`
      )
    }

    // 1) 노출 대상 엔트리만 추림: 경로에 숨김 세그먼트(.foo)가 있으면 제외,
    //    blob 은 지원 확장자만, tree(디렉토리)는 모두 유지 (기존 필터와 동일).
    const nodes = new Map<string, ContentTreeItem>()
    for (const entry of resp.data.tree) {
      const { path: entryPath, type, sha, size } = entry
      if (!entryPath || !sha || (type !== 'blob' && type !== 'tree')) {
        continue
      }
      const segments = entryPath.split('/')
      if (segments.some((seg) => seg.startsWith('.'))) {
        continue
      }
      const name = segments[segments.length - 1]
      const isDir = type === 'tree'
      if (!isDir && !isVisibleFile(name)) {
        continue
      }
      const content = {
        sha,
        path: entryPath,
        name,
        type: isDir ? 'dir' : 'file',
        size: size ?? 0,
      } as unknown as ContentItem
      nodes.set(entryPath, isDir ? { content, children: [] } : { content })
    }

    // 2) 평면 노드를 부모-자식으로 연결. Git Trees 는 지원 확장자 밖의 blob 도
    //    포함하므로 부모 디렉토리는 항상 존재한다.
    const roots: ContentTreeItem[] = []
    for (const [entryPath, item] of nodes) {
      const lastSlash = entryPath.lastIndexOf('/')
      const parent = lastSlash === -1 ? undefined : nodes.get(entryPath.slice(0, lastSlash))
      if (parent?.children) {
        parent.children.push(item)
      } else if (lastSlash === -1) {
        roots.push(item)
      }
    }

    // 3) 시작 경로가 주어지면 해당 노드의 children 을, 아니면 루트를 반환.
    if (path) {
      return nodes.get(path)?.children ?? []
    }
    return roots
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error(e)
    return []
  }
}

function b64DecodeUnicode(str: string): string {
  if (typeof window !== 'undefined' && 'atob' in window && 'decodeURIComponent' in window) {
    return decodeURIComponent(
      Array.prototype.map
        .call(atob(str), (c: string) => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)
        })
        .join('')
    )
  }
  return ''
}

export async function getFlashCardContent(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  path: string
): Promise<FlashCardContent | undefined> {
  try {
    const resp = await octokit.rest.repos.getContent({
      ...repoIdentifier,
      path,
    })
    const contentItem = resp.data as ContentItem
    const content = b64DecodeUnicode((contentItem as unknown as { content: string })?.content || '')

    if (path.endsWith('.fm.json')) {
      const flashManJson = JSON.parse(content) as FlashManJson
      return {
        ...contentItem,
        flashCardItems: flashManJson.items.map(({ id, question, answer }, i) => ({
          itemId: id,
          q: question,
          a: answer,
          lineNo: i,
        })),
      }
    }

    const lines = content.split('\n')
    const flashCardItems = lines
      .map((l, id) => {
        const [q, a] = l.replace(/\t+/, '\t').split('\t')
        return { lineNo: id, q, a: a?.replace(/^\| /, '') }
      })
      .filter(({ q, a }) => Boolean(q) && Boolean(a))

    return {
      ...contentItem,
      flashCardItems,
    }
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error(e)
  }
}

function isNotFound(e: unknown): boolean {
  return typeof e === 'object' && e !== null && (e as { status?: number }).status === 404
}

/** 힌트 인덱스를 가질 수 있는 카드 파일인지 (v2 `.fm.json` 또는 레거시 v1 `.fm.md`). */
export function isHintableCardFile(path: string): boolean {
  return (path.endsWith('.fm.json') && !path.endsWith('.fm.hints.json')) || path.endsWith('.fm.md')
}

/**
 * 힌트 문서를 읽는다. 산출물 필드의 경로 값은 **이 문서가 있는 디렉토리 기준 상대 경로**이므로
 * 문서와 함께 그 base dir(repo 루트 기준)을 돌려준다. 경로 계산은 `lib/hints.ts` 참고.
 * 힌트 문서가 없는 저장소가 대부분이므로 404 → null은 정상 흐름이다.
 */
export async function getHintsDoc(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  hintsDocPath: string
): Promise<HintsDoc | null> {
  try {
    const resp = await octokit.rest.repos.getContent({ ...repoIdentifier, path: hintsDocPath })
    const content = b64DecodeUnicode((resp.data as { content?: string }).content || '')
    const parsed = JSON.parse(content) as FlashManHintJson
    if (parsed?.version !== 1 || !Array.isArray(parsed.items)) {
      return null
    }
    return { doc: parsed, baseDir: dirnameOf(hintsDocPath) }
  } catch (e) {
    if (!isNotFound(e)) {
      // eslint-disable-next-line no-console
      console.error(e)
    }
    return null
  }
}

/** 텍스트 파일 내용을 읽는다. 없으면(404) null. */
export async function getTextFileContent(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  path: string
): Promise<string | null> {
  try {
    const resp = await octokit.rest.repos.getContent({ ...repoIdentifier, path })
    return b64DecodeUnicode((resp.data as { content?: string }).content || '')
  } catch (e) {
    if (!isNotFound(e)) {
      // eslint-disable-next-line no-console
      console.error(e)
    }
    return null
  }
}

const IMAGE_MIME: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  webp: 'image/webp',
  svg: 'image/svg+xml',
}

/** ArrayBuffer를 base64 문자열로 인코딩한다 (큰 파일에서 call stack 초과를 피하려 청크 단위). */
function arrayBufferToBase64(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer)
  let binary = ''
  const chunk = 0x8000
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk))
  }
  return btoa(binary)
}

/**
 * 이미지 파일을 data URL로 읽는다. 없으면(404) null.
 *
 * Contents API는 1MB 이하 파일만 base64 `content`를 채워준다. 1MB를 초과하면
 * `content`가 빈 문자열(`encoding: "none"`)로 오므로, 이 경우 `Accept:
 * application/vnd.github.raw`로 원시 바이트를 다시 받아 인코딩한다.
 *
 * 이 raw 요청은 octokit(`octokit.rest`/`octokit.request`) 대신 순수 `fetch`로
 * 보낸다. octokit 응답 파서는 raw 응답의 content-type에 붙는 `charset=utf-8`을
 * 보고 `response.text()`로 읽어 바이너리를 손상시키기 때문이다. 대신 첫 응답의
 * `data.url`(ref 포함)로 직접 요청해 `arrayBuffer()`로 받는다. 인증 토큰은
 * `octokit.auth()`에서 얻어 private 저장소도 지원한다.
 */
export async function getImageDataUrl(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  path: string
): Promise<string | null> {
  const ext = path.split('.').pop()?.toLowerCase() ?? ''
  const mime = IMAGE_MIME[ext] ?? 'image/png'
  try {
    const { data } = await octokit.rest.repos.getContent({ ...repoIdentifier, path })

    if (data instanceof Array) {
      return null
    }

    if (data.type !== 'file') {
      return null
    }

    const { content } = data
    if (content) {
      return `data:${mime};base64,${content.replace(/\n/g, '')}`
    }

    // content가 비어 있으면 1MB 초과 파일. data.url에 raw Accept로 직접 요청한다.
    const auth = (await octokit.auth()) as { token?: string }
    const resp = await fetch(data.url, {
      headers: {
        Accept: 'application/vnd.github.raw',
        ...(auth?.token ? { Authorization: `Bearer ${auth.token}` } : {}),
      },
    })
    if (!resp.ok) {
      return null
    }
    const buffer = await resp.arrayBuffer()
    return `data:${mime};base64,${arrayBufferToBase64(buffer)}`
  } catch (e) {
    if (!isNotFound(e)) {
      // eslint-disable-next-line no-console
      console.error(e)
    }
    return null
  }
}

function countFmFiles(tree: ContentTreeItem[]): number {
  return tree.reduce((count, item) => {
    if (
      item.content.type === 'file' &&
      (item.content.name.endsWith('.fm.json') || item.content.name.endsWith('.fm.md'))
    ) {
      return count + 1
    }
    return count + (item.children ? countFmFiles(item.children) : 0)
  }, 0)
}

export async function countFlashManFiles(
  octokit: Octokit,
  repoIdentifier: RepoIdentifier,
  path: string
): Promise<number> {
  const tree = await getContentTree(octokit, repoIdentifier, path)
  return countFmFiles(tree)
}

/**
 * 여러 경로의 "최근 커밋일(committedDate)"을 GraphQL 한 번의 요청으로 가져온다.
 *
 * REST Contents API는 파일의 수정 시각을 제공하지 않아, 정렬을 위해 경로마다
 * 커밋 API를 호출하면 N+1 요청이 발생한다. GraphQL의 alias 로 각 경로의
 * `history(first: 1, path: ...)` 를 하나의 쿼리에 묶어 왕복 1회로 처리한다.
 *
 * GraphQL API는 인증이 필수이므로, 토큰이 없는 Octokit 인스턴스에서는
 * 요청이 실패한다. 호출부에서 토큰 유무를 확인하거나, 실패 시 빈 맵으로
 * graceful degradation 되도록 한다.
 *
 * @returns path -> ISO8601 committedDate 매핑 (조회 실패 시 빈 객체)
 */
export async function getLastModifiedMap(
  octokit: Octokit,
  { owner, repo }: RepoIdentifier,
  paths: string[],
  ref = 'HEAD'
): Promise<Record<string, string>> {
  if (paths.length === 0) {
    return {}
  }

  const aliases = paths
    .map(
      (path, i) =>
        `f${i}: object(expression: ${JSON.stringify(ref)}) {
          ... on Commit {
            history(first: 1, path: ${JSON.stringify(path)}) {
              nodes { committedDate }
            }
          }
        }`
    )
    .join('\n')

  const query = `query ($owner: String!, $repo: String!) {
    repository(owner: $owner, name: $repo) {
      ${aliases}
    }
  }`

  try {
    const data = await octokit.graphql<{
      repository: Record<string, { history: { nodes: { committedDate: string }[] } } | null> | null
    }>(query, { owner, repo })

    const repository = data.repository
    const result: Record<string, string> = {}
    paths.forEach((path, i) => {
      const committedDate = repository?.[`f${i}`]?.history?.nodes?.[0]?.committedDate
      if (committedDate) {
        result[path] = committedDate
      }
    })
    return result
  } catch (e) {
    // eslint-disable-next-line no-console
    console.error(e)
    return {}
  }
}
